1	package agentusage
2	
3	import (
4		"cmp"
5		"errors"
6		"fmt"
7		"io"
8		"os"
9		"path/filepath"
10		"slices"
11		"strings"
12		"sync/atomic"
13		"time"
14	)
15	
16	// fileCursor is the read position of one transcript. Values only: no pointer
17	// except the immutable os.FileInfo.
18	type fileCursor struct {
19		path     string      // full path, never logged
20		name     string      // sanitized base name (FileIssue.File, TruncatedFiles)
21		agent    string      // key of the agent in a table: "" for the parent, else rank
22		label    string      // sanitized agent ID shown to the user; "" for the parent
23		rank     string      // position rank of the file (parentRank or transcriptRank)
24		id       os.FileInfo // from the open handle's Stat at the last read; nil before
25		offset   int64       // just past the last complete line folded in
26		size     int64       // file size at the last read
27		modTime  time.Time   // Lstat mtime at the last listing
28		skipFrom int64       // start of an oversized line still being written, or -1
29		tail     bool        // an incomplete line follows offset (TruncatedFiles)
30		issue    IssueKind   // state issue of the last read (D6), valid if hasIssue
31		issueOff int64
32		hasIssue bool
33	}
34	
35	// newFileCursor returns the cursor of a transcript not read yet.
36	func newFileCursor(path, name, agent, rank string) fileCursor {
37		return fileCursor{path: path, name: name, agent: agent, rank: rank, skipFrom: -1}
38	}
39	
40	// transcriptFile is what readFile needs from an open transcript; *os.File
41	// satisfies it.
42	type transcriptFile interface {
43		io.Reader
44		io.ReaderAt
45		io.Seeker
46		io.Closer
47		Stat() (os.FileInfo, error)
48	}
49	
50	// openTranscript opens a transcript through openPlain. A var so tests can
51	// count opens and bytes read.
52	var openTranscript = func(path string) (transcriptFile, error) {
53		f, err := openPlain(path, false)
54		if err != nil {
55			return nil, err
56		}
57		if f == nil {
58			return nil, errNotRegular
59		}
60		return f, nil
61	}
62	
63	// fileRead is the outcome of reading one file from its cursor.
64	type fileRead struct {
65		next  fileCursor
66		part  *table // lines folded from the new bytes; nil when nothing was read
67		reset bool   // not an append (D4): the caller restarts the whole session
68		err   error  // why the file could not be opened or read at all, if so
69	}
70	
71	// read reports whether the cursor has already read part of its file.
72	func (fc fileCursor) read() bool { return fc.offset > 0 || fc.skipFrom >= 0 || fc.id != nil }
73	
74	// quiet reports whether the file is, as far as Lstat can tell, exactly what the
75	// last read saw. A cursor holding a read error never is: the bytes between
76	// its offset and the failure must be read again.
77	func (fc fileCursor) quiet(li os.FileInfo) bool {
78		if fc.id == nil || (fc.hasIssue && fc.issue == IssueReadError) {
79			return false
80		}
81		return li.Size() == fc.size && os.SameFile(li, fc.id)
82	}
83	
84	// failRead is the outcome of a path that cannot be read: a reset when the file
85	// was read before (D4), else a state issue cleared by the next success (D6).
86	func failRead(fc fileCursor, err error) fileRead {
87		if fc.read() {
88			return fileRead{next: fc, reset: true, err: err}
89		}
90		fc.issue, fc.issueOff, fc.hasIssue = IssueOpenFailed, 0, true
91		return fileRead{next: fc, err: err}
92	}
93	
94	// isAppend reports whether the open file is the one fc read, only grown (D4).
95	func (fc fileCursor) isAppend(f transcriptFile, fi os.FileInfo) bool {
96		if (fc.id != nil && !os.SameFile(fi, fc.id)) || fi.Size() < fc.size {
97			return false
98		}
99		if fc.offset == 0 {
100			return true
101		}
102		var b [1]byte
103		n, _ := f.ReadAt(b[:], fc.offset-1)
104		return n == 1 && b[0] == '\n'
105	}
106	
107	// readFile reads what was appended to fc's file since fc. now clamps mtimes.
108	// It never follows a link and never opens a non-regular file.
109	func readFile(fc fileCursor, now time.Time) fileRead {
110		li, err := os.Lstat(fc.path)
111		if err != nil {
112			return failRead(fc, err)
113		}
114		if !li.Mode().IsRegular() {
115			return failRead(fc, errNotRegular)
116		}
117		fc.modTime = li.ModTime()
118		if fc.modTime.After(now) {
119			fc.modTime = now
120		}
121		if fc.quiet(li) {
122			return fileRead{next: fc}
123		}
124		f, err := openTranscript(fc.path)
125		if err != nil {
126			return failRead(fc, err)
127		}
128		defer func() { _ = f.Close() }()
129		fi, err := f.Stat()
130		if err != nil {
131			return failRead(fc, err)
132		}
133		if !fc.isAppend(f, fi) {
134			return fileRead{next: fc, reset: true}
135		}
136		return fc.scan(f, fi)
137	}
138	
139	// scan folds the lines past the cursor into a new table and returns the
140	// advanced cursor. A line held back is read again next time (D1); an
141	// oversized one still being written is resumed in skip mode (D2).
142	func (fc fileCursor) scan(f transcriptFile, fi os.FileInfo) fileRead {
143		start := fc.offset
144		if fc.skipFrom >= 0 {
145			start = fc.size
146		}
147		if _, err := f.Seek(start, io.SeekStart); err != nil {
148			return failRead(fc, err)
149		}
150		part := newTable()
151		res, err := scanFrom(f, start, fc.skipFrom, MaxLineBytes, func(line []byte, off int64) {
152			part.addLine(fc.agent, fc.name, pos{rank: fc.rank, off: off}, line)
153		})
154		for _, off := range res.OversizedAt {
155			part.addOversized(fc.name, pos{rank: fc.rank, off: off})
156		}
157		next := fc
158		next.id, next.size, next.skipFrom = fi, res.End, res.SkipFrom
159		next.offset, next.tail = res.Consumed, len(res.Tail) > 0
160		if fc.skipFrom >= 0 && res.Consumed == start {
161			next.offset = fc.offset // the oversized line has not ended yet
162		}
163		next.issue, next.issueOff, next.hasIssue = 0, 0, false
164		if err != nil {
165			next.issue, next.issueOff, next.hasIssue = IssueReadError, next.offset, true
166		}
167		return fileRead{next: next, part: part}
168	}
169	
170	// ErrStaleDelta is returned by Apply for a delta that was not read from the
171	// aggregate's current cursor. The aggregate is unchanged; read again from
172	// Cursor().
173	var ErrStaleDelta = errors.New("agentusage: delta does not follow the aggregate's cursor")
174	
175	// readMetaFile reads one meta file; a var so tests can count meta reads (D7).
176	// The session reader goes through it.
177	var readMetaFile = readMeta
178	
179	// timeNow is time.Now; a var for tests.
180	var timeNow = time.Now
181	
182	// aggregateIDs hands out the identity of each Aggregate (D9).
183	var aggregateIDs atomic.Uint64
184	
185	// metaCursor is the last listing of one sub-agent's meta file and what was
186	// read from it. Values only, so a cursor stays a plain copyable value.
187	type metaCursor struct {
188		rank       string // rank of the sub-agent's transcript
189		path       string // "" when absent
190		size       int64
191		modTime    time.Time
192		unreadable bool
193		typ        string
194		state      State
195		depth      int
196	}
197	
198	// sameResult reports whether o tells the same story as m: Lstat details such
199	// as the mtime are not part of it.
200	func (m metaCursor) sameResult(o metaCursor) bool {
201		return m.rank == o.rank && (m.path == "") == (o.path == "") && m.unreadable == o.unreadable &&
202			m.typ == o.typ && m.state == o.state && m.depth == o.depth
203	}
204	
205	// unchangedSince reports whether the file Lstat described by fi is the one m
206	// was read from.
207	func (m metaCursor) unchangedSince(path string, fi os.FileInfo) bool {
208		return fi != nil && m.path == path && m.size == fi.Size() && m.modTime.Equal(fi.ModTime())
209	}
210	
211	// Cursor records how far each file of one session has been read. It is a
212	// plain value: copying it is safe and ReadDelta never mutates it. It holds
213	// full paths, so it must never be logged; String and GoString redact them.
214	type Cursor struct {
215		parent string // parent transcript path
216		id     uint64 // identity of the aggregate it came from
217		seq    uint64 // number of deltas applied when it was taken
218		fresh  bool   // nothing applied yet, or rewound: the next delta is Full
219		files  []fileCursor
220		metas  []metaCursor
221	}
222	
223	// Rewound returns c with every position cleared, keeping its identity: the
224	// next ReadDelta reads every file from the start and returns a Full delta.
225	func (c Cursor) Rewound() Cursor {
226		files := make([]fileCursor, len(c.files))
227		for i, fc := range c.files {
228			files[i] = newFileCursor(fc.path, fc.name, fc.agent, fc.rank)
229			files[i].label = fc.label
230		}
231		c.files, c.metas, c.fresh = files, nil, true
232		return c
233	}
234	
235	// String redacts the paths the cursor holds.
236	func (c Cursor) String() string { return fmt.Sprintf("agentusage.Cursor{files: %d}", len(c.files)) }
237	
238	// GoString redacts the paths the cursor holds.
239	func (c Cursor) GoString() string { return c.String() }
240	
241	// Delta is what ReadDelta found since a Cursor: the new complete lines of each
242	// file, already deduplicated, the files that appeared, the meta files that
243	// changed, and the positions to resume from. Paths live in unexported fields
244	// and are never printed.
245	type Delta struct {
246		valid     bool   // false for the zero Delta, which was never read
247		id, seq   uint64 // the cursor it was read from
248		full      bool
249		changed   bool
250		sessionID string
251		files     []fileCursor
252		metas     []metaCursor
253		part      *table
254		parentErr error // why the parent could not be opened, for ParseSession
255	}
256	
257	// Full reports whether the delta was read from the start of every file (first
258	// read, Rewound cursor, or a change that was not an append).
259	func (d Delta) Full() bool { return d.full }
260	
261	// Empty reports whether nothing changed: no new complete line, no file added
262	// or gone, no meta change, no change of a file's end-of-file state (an
263	// incomplete last line appearing or disappearing) or of its read issue. A
264	// held-back line that only grows, a persistent issue, or an mtime that alone
265	// moved do not count.
266	func (d Delta) Empty() bool { return !d.changed }
267	
268	// String shows counts only.
269	func (d Delta) String() string {
270		return fmt.Sprintf("agentusage.Delta{full: %t, empty: %t, files: %d}", d.full, d.Empty(), len(d.files))
271	}
272	
273	// GoString shows counts only.
274	func (d Delta) GoString() string { return d.String() }
275	
276	// Aggregate is a session's usage built from successive deltas. It is not safe
277	// for concurrent use: one goroutine (Bubble Tea's Update) owns it.
278	type Aggregate struct {
279		parent    string
280		id, seq   uint64
281		fresh     bool
282		sessionID string
283		files     []fileCursor // parent first, then sub-agents by rank
284		metas     []metaCursor
285		t         *table
286	}
287	
288	// String shows counts only: an Aggregate holds paths, and the value receiver
289	// also covers a dereferenced *a.
290	func (a Aggregate) String() string {
291		return fmt.Sprintf("agentusage.Aggregate{files: %d, applied: %d}", len(a.files), a.seq)
292	}
293	
294	// GoString shows counts only.
295	func (a Aggregate) GoString() string { return a.String() }
296	
297	// NewAggregate starts an empty aggregate for the session whose parent
298	// transcript is parentTranscript (<dir>/<uuid>.jsonl). It does no I/O.
299	func NewAggregate(parentTranscript string) *Aggregate {
300		base := filepath.Base(parentTranscript)
301		return &Aggregate{
302			parent:    parentTranscript,
303			id:        aggregateIDs.Add(1),
304			fresh:     true,
305			sessionID: sanitizeLabel(strings.TrimSuffix(base, transcriptExt)),
306			files:     []fileCursor{newFileCursor(parentTranscript, sanitizeLabel(base), "", parentRank)},
307			t:         newTable(),
308		}
309	}
310	
311	// Cursor returns a copy of the aggregate's position, to hand to ReadDelta.
312	func (a *Aggregate) Cursor() Cursor {
313		return Cursor{
314			parent: a.parent, id: a.id, seq: a.seq, fresh: a.fresh,
315			files: slices.Clone(a.files), metas: slices.Clone(a.metas),
316		}
317	}
318	
319	// Apply folds d in, or replaces everything with it when d.Full(). It returns
320	// ErrStaleDelta, and changes nothing, if d was not read from a.Cursor(). It
321	// takes ownership of d.
322	func (a *Aggregate) Apply(d Delta) error {
323		if !d.valid || d.id != a.id || d.seq != a.seq {
324			return ErrStaleDelta
325		}
326		switch {
327		case d.full:
328			a.t = boundedTable(d.part)
329		case d.part != nil:
330			a.t.mergeCapped(d.part)
331		}
332		a.files, a.metas, a.sessionID = d.files, d.metas, d.sessionID
333		a.fresh = false
334		a.seq++
335		return nil
336	}
337	
338	// boundedTable returns part, or a copy of it holding at most maxNoIDEntries
339	// entries without a message id.
340	func boundedTable(part *table) *table {
341		if part == nil {
342			return newTable()
343		}
344		if part.noID <= maxNoIDEntries {
345			return part
346		}
347		t := newTable()
348		t.mergeCapped(part)
349		return t
350	}
351	
352	// Usage returns the session's usage so far, same shape and rules as
353	// ParseSession; the result shares no memory with the aggregate.
354	func (a *Aggregate) Usage() Usage {
355		agents := []Agent{{Main: true, State: StateUnknown}}
356		var diag Diagnostics
357		var truncated []string
358		var issues []issueAt
359		metaOf := make(map[string]metaCursor, len(a.metas))
360		for _, m := range a.metas {
361			metaOf[m.rank] = m
362		}
363		for _, fc := range a.files {
364			if fc.tail {
365				truncated = append(truncated, fc.name)
366			}
367			if fc.hasIssue {
368				fi := FileIssue{File: fc.name, Offset: fc.issueOff, Kind: fc.issue}
369				issues = append(issues, issueAt{p: pos{rank: fc.rank, off: fc.issueOff}, fi: fi})
370			}
371			if fc.rank != parentRank {
372				agents = append(agents, subAgent(fc, metaOf[fc.rank], &diag))
373			}
374		}
375		agents, diag2, versions := a.t.finishWith(agents, issues)
376		diag2.MetaMissing, diag2.MetaUnreadable, diag2.TruncatedFiles = diag.MetaMissing, diag.MetaUnreadable, truncated
377		return Usage{SessionID: a.sessionID, Agents: agents, Versions: versions, Diagnostics: diag2}
378	}
379	
380	// subAgent builds a sub-agent's identity from its meta cursor, counting a
381	// missing or unreadable meta file in diag.
382	func subAgent(fc fileCursor, m metaCursor, diag *Diagnostics) Agent {
383		ag := Agent{ID: fc.label, key: fc.rank}
384		switch {
385		case m.path == "":
386			diag.MetaMissing++
387		case m.unreadable:
388			diag.MetaUnreadable++
389		default:
390			ag.Type, ag.State, ag.SpawnDepth = m.typ, m.state, m.depth
391		}
392		return ag
393	}
394	
395	// ReadDelta lists the session again (parent, subagents/, meta files, Lstat
396	// only) and reads what was appended since c. Files whose size did not change
397	// are not opened. It fails only if the session cannot be listed; errors name
398	// base names only, and on error there is nothing to apply. A parent that is
399	// missing, unreadable or not a regular file is not an error: the delta then
400	// carries an IssueOpenFailed on the parent (Full at tick 0, then Empty while
401	// it persists), which the caller must detect through the parent's FileIssue.
402	//
403	// Declared oracle gap (meta files): a meta file that cannot be read (chmod 000)
404	// counts as MetaUnreadable here, whereas ParseSession(LocateSession) counts it
405	// MetaMissing. Meta files are compared by Lstat size and mtime (D7), so an
406	// unreadable meta stays so after chmod +r until it is rewritten.
407	func ReadDelta(c Cursor) (Delta, error) {
408		files, infos, err := listForPoll(c.parent)
409		if err != nil {
410			return Delta{}, err
411		}
412		return readSession(files, infos, c, timeNow()), nil
413	}
414	
415	// listForPoll lists the session like LocateSession, with meta presence from
416	// Lstat only (D7), and returns the Lstat result of each meta file found.
417	func listForPoll(parent string) (SessionFiles, map[string]os.FileInfo, error) {
418		infos := map[string]os.FileInfo{}
419		files, err := locateSession(parent, func(path string) bool {
420			fi, err := os.Lstat(path)
421			if err != nil || !fi.Mode().IsRegular() {
422				return false
423			}
424			infos[path] = fi
425			return true
426		})
427		return files, infos, err
428	}
429	
430	// target is one transcript of a listing, with its meta file ("" if absent).
431	type target struct {
432		fc   fileCursor
433		meta string
434	}
435	
436	// sessionTargets turns a listing into fresh cursors: the parent first, then
437	// the sub-agents in rank order, which is the order ParseSession reads them.
438	func sessionTargets(files SessionFiles) []target {
439		out := []target{{fc: newFileCursor(files.Parent, sanitizeLabel(filepath.Base(files.Parent)), "", parentRank)}}
440		for _, sa := range files.SubAgents {
441			id := sanitizeLabel(sa.ID)
442			name := sanitizeLabel(filepath.Base(sa.Transcript))
443			rank := transcriptRank(id, name, sa.ID, sa.Transcript)
444			fc := newFileCursor(sa.Transcript, name, rank, rank)
445			fc.label = id
446			out = append(out, target{fc: fc, meta: sa.Meta})
447		}
448		slices.SortFunc(out[1:], func(a, b target) int { return cmp.Compare(a.fc.rank, b.fc.rank) })
449		return out
450	}
451	
452	// readSession reads the files of a listing from c. A change that is not an
453	// append (D4) restarts every file from the start and the delta is Full.
454	// ParseSession passes a fresh cursor and no meta Lstat information.
455	func readSession(files SessionFiles, infos map[string]os.FileInfo, c Cursor, now time.Time) Delta {
456		targets := sessionTargets(files)
457		full := c.fresh
458		p, ok := readTargets(targets, c, now)
459		if !ok {
460			c, full = c.Rewound(), true
461			// ok is true by construction: a rewound cursor knows no file, so no
462			// file can ask for another restart.
463			p, _ = readTargets(targets, c, now)
464		}
465		metas, metaChanged := readMetas(targets[1:], infos, c)
466		return Delta{
467			valid: true, id: c.id, seq: c.seq, full: full,
468			changed:   full || p.changed || metaChanged,
469			sessionID: sanitizeLabel(files.ID),
470			files:     p.files, metas: metas, part: p.part, parentErr: p.parentErr,
471		}
472	}
473	
474	// sessionPass is the outcome of one pass over the transcripts.
475	type sessionPass struct {
476		files     []fileCursor
477		part      *table
478		changed   bool
479		parentErr error
480	}
481	
482	// readTargets reads every target from its cursor in c, or from the start when
483	// c does not know it. ok is false when a file asks for a restart (D4): a
484	// file read before is gone, or was not simply appended to.
485	func readTargets(targets []target, c Cursor, now time.Time) (sessionPass, bool) {
486		prior := make(map[string]fileCursor, len(c.files))
487		for _, fc := range c.files {
488			prior[fc.rank] = fc
489		}
490		var p sessionPass
491		for _, tg := range targets {
492			fc, had := prior[tg.fc.rank]
493			delete(prior, tg.fc.rank)
494			if !had {
495				fc, p.changed = tg.fc, true
496			}
497			fr := readFile(fc, now)
498			if fr.reset {
499				return sessionPass{}, false
500			}
501			if fr.next.rank == parentRank && fr.err != nil {
502				p.parentErr = fr.err
503			}
504			p.changed = p.changed || fr.part.hasLines() || fc.issueState() != fr.next.issueState() ||
505				fc.tail != fr.next.tail
506			p.files = append(p.files, fr.next)
507			p.addPart(fr.part)
508		}
509		for _, gone := range prior {
510			if gone.read() {
511				return sessionPass{}, false
512			}
513			p.changed = true
514		}
515		return p, true
516	}
517	
518	// addPart folds the lines of one file into the pass, spilling no-id lines past
519	// maxNoIDEntries like a sequential read does (totals stay exact).
520	func (p *sessionPass) addPart(part *table) {
521		switch {
522		case part == nil:
523		case p.part == nil:
524			p.part = part
525		default:
526			p.part.mergeCapped(part) // keeps the pass within the no-id bound across files
527		}
528	}
529	
530	// issueState is what a cursor says about its last read, for comparisons.
531	type issueState struct {
532		has  bool
533		kind IssueKind
534		off  int64
535	}
536	
537	func (fc fileCursor) issueState() issueState {
538		return issueState{has: fc.hasIssue, kind: fc.issue, off: fc.issueOff}
539	}
540	
541	// readMetas returns the meta cursors of the sub-agents in targets, reading a
542	// meta file only when its Lstat size or mtime differs from c's (D7), and
543	// whether any of them tells something new. An unreadable meta file is
544	// MetaUnreadable here but MetaMissing for ParseSession(LocateSession): a
545	// declared oracle gap, see ReadDelta.
546	func readMetas(subs []target, infos map[string]os.FileInfo, c Cursor) ([]metaCursor, bool) {
547		prior := make(map[string]metaCursor, len(c.metas))
548		for _, m := range c.metas {
549			prior[m.rank] = m
550		}
551		out := make([]metaCursor, 0, len(subs))
552		changed := false
553		for _, tg := range subs {
554			m := nextMeta(tg, infos, prior)
555			old, had := prior[m.rank]
556			changed = changed || !had || !old.sameResult(m)
557			out = append(out, m)
558		}
559		return out, changed
560	}
561	
562	// nextMeta returns the meta cursor of one sub-agent: the prior one when its
563	// file did not change, else a fresh read through readMetaFile.
564	func nextMeta(tg target, infos map[string]os.FileInfo, prior map[string]metaCursor) metaCursor {
565		m := metaCursor{rank: tg.fc.rank}
566		if tg.meta == "" {
567			return m
568		}
569		m.path = tg.meta
570		fi := infos[tg.meta]
571		if fi != nil {
572			m.size, m.modTime = fi.Size(), fi.ModTime()
573		}
574		if old, ok := prior[m.rank]; ok && old.unchangedSince(tg.meta, fi) {
575			return old
576		}
577		md, err := readMetaFile(tg.meta)
578		if err != nil {
579			m.unreadable = true
580			return m
581		}
582		m.typ, m.state, m.depth = md.AgentType, md.state(), md.SpawnDepth
583		return m
584	}
585	
586	// Activity tells a poller when a session has gone quiet.
587	type Activity struct {
588		// LastChange is when the session last changed. Zero before the first Apply.
589		LastChange time.Time
590		// Unfinished counts sub-agents whose meta says finished: false.
591		Unfinished int
592	}
593	
594	// Settled reports whether polling can stop: something was applied, no
595	// sub-agent is unfinished, and nothing changed for at least quiet before now.
596	func (a Activity) Settled(now time.Time, quiet time.Duration) bool { return false } // TODO(DEVDESK-44 step 5)
597	
598	// Activity returns what the reads applied so far say about the session's life.
599	func (a *Aggregate) Activity() Activity { return Activity{} } // TODO(DEVDESK-44 step 5)
600

