298	// The parent cannot be opened but ReadDelta reports no error: the delta
299	// carries IssueOpenFailed on the parent. Decision: such a session is NEVER
300	// settled, whatever else is quiet, so a poller keeps retrying and a transient
301	// failure heals. It is settled again after a successful read plus quiet.
302	func TestActivityWithAnUnreadableParent(t *testing.T) {
303		far := actBase.Add(1000 * time.Hour)
304		for _, tc := range []struct {
305			name string
306			meta string
307		}{
308			{"all sub-agents finished", metaFinished},
309			{"sub-agent unknown", metaUnknown},
310		} {
311			t.Run(tc.name, func(t *testing.T) {
312				clock := setClock(t, actBase)
313				s := newSess(t)
314				s.build(metaSet{"a1": tc.meta}, actBase)
315				orig := openTranscript
316				failing := true
317				swapOpen(t, func(path string) (transcriptFile, error) {
318					if failing && path == s.parent() {
319						return nil, errors.New("injected open failure")
320					}
321					return orig(path)
322				})
323				a := NewAggregate(s.parent())
324				readApply(t, a)
325				if !hasIssue(a.Usage(), incSessUUID+".jsonl", IssueOpenFailed) {
326					t.Fatal("setup: the parent must carry IssueOpenFailed")
327				}
328				if a.Activity().Settled(far, actQuiet) {
329					t.Error("an unreadable parent must keep the session unsettled, however quiet")
330				}
331				*clock = far // still failing on later passes: still unsettled
332				readApply(t, a)
333				if a.Activity().Settled(far.Add(time.Hour), actQuiet) {
334					t.Error("still unsettled while the parent stays unreadable")
335				}
336				failing = false
337				readApply(t, a) // the issue clears
338				if hasIssue(a.Usage(), incSessUUID+".jsonl", IssueOpenFailed) {
339					t.Fatal("setup: the issue must clear once the parent opens")
340				}
341				if !a.Activity().Settled(far.Add(time.Hour), actQuiet) {
342					t.Error("settled again after a successful read and quiet")
343				}
344			})
345		}
346	}
