297	// NewAggregate starts an empty aggregate for the session whose parent
298	// transcript is parentTranscript (<dir>/<uuid>.jsonl). It does no I/O.
299	func NewAggregate(parentTranscript string) *Aggregate {
300		base := filepath.Base(parentTranscript)
301		return &Aggregate{
302			parent:    parentTranscript,
303			id:        aggregateIDs.Add(1),
304			fresh:     true,
305			sessionID: sanitizeLabel(strings.TrimSuffix(base, transcriptExt)),
306			files:     []fileCursor{newFileCursor(parentTranscript, sanitizeLabel(base), "", parentRank)},
307			t:         newTable(),
308		}
309	}
