311	// Cursor returns a copy of the aggregate's position, to hand to ReadDelta.
312	func (a *Aggregate) Cursor() Cursor {
313		return Cursor{
314			parent: a.parent, id: a.id, seq: a.seq, fresh: a.fresh,
315			files: slices.Clone(a.files), metas: slices.Clone(a.metas),
316		}
317	}
