319	// Apply folds d in, or replaces everything with it when d.Full(). It returns
320	// ErrStaleDelta, and changes nothing, if d was not read from a.Cursor(). It
321	// takes ownership of d.
322	func (a *Aggregate) Apply(d Delta) error {
323		if !d.valid || d.id != a.id || d.seq != a.seq {
324			return ErrStaleDelta
325		}
326		switch {
327		case d.full:
328			a.t = boundedTable(d.part)
329		case d.part != nil:
330			a.t.mergeCapped(d.part)
331		}
332		a.files, a.metas, a.sessionID = d.files, d.metas, d.sessionID
333		a.fresh = false
334		a.seq++
335		return nil
336	}
337	
338	// boundedTable returns part, or a copy of it holding at most maxNoIDEntries
339	// entries without a message id.
340	func boundedTable(part *table) *table {
341		if part == nil {
342			return newTable()
343		}
344		if part.noID <= maxNoIDEntries {
345			return part
346		}
347		t := newTable()
348		t.mergeCapped(part)
349		return t
350	}
