352	// Usage returns the session's usage so far, same shape and rules as
353	// ParseSession; the result shares no memory with the aggregate.
354	func (a *Aggregate) Usage() Usage {
355		agents := []Agent{{Main: true, State: StateUnknown}}
356		var diag Diagnostics
357		var truncated []string
358		var issues []issueAt
359		metaOf := make(map[string]metaCursor, len(a.metas))
360		for _, m := range a.metas {
361			metaOf[m.rank] = m
362		}
363		for _, fc := range a.files {
364			if fc.tail {
365				truncated = append(truncated, fc.name)
366			}
367			if fc.hasIssue {
368				fi := FileIssue{File: fc.name, Offset: fc.issueOff, Kind: fc.issue}
369				issues = append(issues, issueAt{p: pos{rank: fc.rank, off: fc.issueOff}, fi: fi})
370			}
371			if fc.rank != parentRank {
372				agents = append(agents, subAgent(fc, metaOf[fc.rank], &diag))
373			}
374		}
375		agents, diag2, versions := a.t.finishWith(agents, issues)
376		diag2.MetaMissing, diag2.MetaUnreadable, diag2.TruncatedFiles = diag.MetaMissing, diag.MetaUnreadable, truncated
377		return Usage{SessionID: a.sessionID, Agents: agents, Versions: versions, Diagnostics: diag2}
378	}
