380	// subAgent builds a sub-agent's identity from its meta cursor, counting a
381	// missing or unreadable meta file in diag.
382	func subAgent(fc fileCursor, m metaCursor, diag *Diagnostics) Agent {
383		ag := Agent{ID: fc.label, key: fc.rank}
384		switch {
385		case m.path == "":
386			diag.MetaMissing++
387		case m.unreadable:
388			diag.MetaUnreadable++
389		default:
390			ag.Type, ag.State, ag.SpawnDepth = m.typ, m.state, m.depth
391		}
392		return ag
393	}
