395	// ReadDelta lists the session again (parent, subagents/, meta files, Lstat
396	// only) and reads what was appended since c. Files whose size did not change
397	// are not opened. It fails only if the session cannot be listed; errors name
398	// base names only, and on error there is nothing to apply. A parent that is
399	// missing, unreadable or not a regular file is not an error: the delta then
400	// carries an IssueOpenFailed on the parent (Full at tick 0, then Empty while
401	// it persists), which the caller must detect through the parent's FileIssue.
402	//
403	// Declared oracle gap (meta files): a meta file that cannot be read (chmod 000)
404	// counts as MetaUnreadable here, whereas ParseSession(LocateSession) counts it
405	// MetaMissing. Meta files are compared by Lstat size and mtime (D7), so an
406	// unreadable meta stays so after chmod +r until it is rewritten.
407	func ReadDelta(c Cursor) (Delta, error) {
408		files, infos, err := listForPoll(c.parent)
409		if err != nil {
410			return Delta{}, err
411		}
412		return readSession(files, infos, c, timeNow()), nil
413	}
414	
415	// listForPoll lists the session like LocateSession, with meta presence from
416	// Lstat only (D7), and returns the Lstat result of each meta file found.
417	func listForPoll(parent string) (SessionFiles, map[string]os.FileInfo, error) {
418		infos := map[string]os.FileInfo{}
419		files, err := locateSession(parent, func(path string) bool {
420			fi, err := os.Lstat(path)
421			if err != nil || !fi.Mode().IsRegular() {
422				return false
423			}
424			infos[path] = fi
425			return true
426		})
427		return files, infos, err
428	}
