430	// target is one transcript of a listing, with its meta file ("" if absent).
431	type target struct {
432		fc   fileCursor
433		meta string
434	}
435	
436	// sessionTargets turns a listing into fresh cursors: the parent first, then
437	// the sub-agents in rank order, which is the order ParseSession reads them.
438	func sessionTargets(files SessionFiles) []target {
439		out := []target{{fc: newFileCursor(files.Parent, sanitizeLabel(filepath.Base(files.Parent)), "", parentRank)}}
440		for _, sa := range files.SubAgents {
441			id := sanitizeLabel(sa.ID)
442			name := sanitizeLabel(filepath.Base(sa.Transcript))
443			rank := transcriptRank(id, name, sa.ID, sa.Transcript)
444			fc := newFileCursor(sa.Transcript, name, rank, rank)
445			fc.label = id
446			out = append(out, target{fc: fc, meta: sa.Meta})
447		}
448		slices.SortFunc(out[1:], func(a, b target) int { return cmp.Compare(a.fc.rank, b.fc.rank) })
449		return out
450	}
451	
452	// readSession reads the files of a listing from c. A change that is not an
453	// append (D4) restarts every file from the start and the delta is Full.
454	// ParseSession passes a fresh cursor and no meta Lstat information.
455	func readSession(files SessionFiles, infos map[string]os.FileInfo, c Cursor, now time.Time) Delta {
456		targets := sessionTargets(files)
457		full := c.fresh
458		p, ok := readTargets(targets, c, now)
459		if !ok {
460			c, full = c.Rewound(), true
461			// ok is true by construction: a rewound cursor knows no file, so no
462			// file can ask for another restart.
463			p, _ = readTargets(targets, c, now)
464		}
465		metas, metaChanged := readMetas(targets[1:], infos, c)
466		return Delta{
467			valid: true, id: c.id, seq: c.seq, full: full,
468			changed:   full || p.changed || metaChanged,
469			sessionID: sanitizeLabel(files.ID),
470			files:     p.files, metas: metas, part: p.part, parentErr: p.parentErr,
471		}
472	}
473	
474	// sessionPass is the outcome of one pass over the transcripts.
475	type sessionPass struct {
476		files     []fileCursor
477		part      *table
478		changed   bool
479		parentErr error
480	}
481	
482	// readTargets reads every target from its cursor in c, or from the start when
483	// c does not know it. ok is false when a file asks for a restart (D4): a
484	// file read before is gone, or was not simply appended to.
485	func readTargets(targets []target, c Cursor, now time.Time) (sessionPass, bool) {
486		prior := make(map[string]fileCursor, len(c.files))
487		for _, fc := range c.files {
488			prior[fc.rank] = fc
489		}
490		var p sessionPass
491		for _, tg := range targets {
492			fc, had := prior[tg.fc.rank]
493			delete(prior, tg.fc.rank)
494			if !had {
495				fc, p.changed = tg.fc, true
496			}
497			fr := readFile(fc, now)
498			if fr.reset {
499				return sessionPass{}, false
500			}
501			if fr.next.rank == parentRank && fr.err != nil {
502				p.parentErr = fr.err
503			}
504			p.changed = p.changed || fr.part.hasLines() || fc.issueState() != fr.next.issueState() ||
505				fc.tail != fr.next.tail
506			p.files = append(p.files, fr.next)
507			p.addPart(fr.part)
508		}
509		for _, gone := range prior {
510			if gone.read() {
511				return sessionPass{}, false
512			}
513			p.changed = true
514		}
515		return p, true
516	}
517	
518	// addPart folds the lines of one file into the pass, spilling no-id lines past
519	// maxNoIDEntries like a sequential read does (totals stay exact).
520	func (p *sessionPass) addPart(part *table) {
521		switch {
522		case part == nil:
523		case p.part == nil:
524			p.part = part
525		default:
526			p.part.mergeCapped(part) // keeps the pass within the no-id bound across files
527		}
528	}
