530	// issueState is what a cursor says about its last read, for comparisons.
531	type issueState struct {
532		has  bool
533		kind IssueKind
534		off  int64
535	}
536	
537	func (fc fileCursor) issueState() issueState {
538		return issueState{has: fc.hasIssue, kind: fc.issue, off: fc.issueOff}
539	}
540	
541	// readMetas returns the meta cursors of the sub-agents in targets, reading a
542	// meta file only when its Lstat size or mtime differs from c's (D7), and
543	// whether any of them tells something new. An unreadable meta file is
544	// MetaUnreadable here but MetaMissing for ParseSession(LocateSession): a
545	// declared oracle gap, see ReadDelta.
546	func readMetas(subs []target, infos map[string]os.FileInfo, c Cursor) ([]metaCursor, bool) {
547		prior := make(map[string]metaCursor, len(c.metas))
548		for _, m := range c.metas {
549			prior[m.rank] = m
550		}
551		out := make([]metaCursor, 0, len(subs))
552		changed := false
553		for _, tg := range subs {
554			m := nextMeta(tg, infos, prior)
555			old, had := prior[m.rank]
556			changed = changed || !had || !old.sameResult(m)
557			out = append(out, m)
558		}
559		return out, changed
560	}
561	
562	// nextMeta returns the meta cursor of one sub-agent: the prior one when its
563	// file did not change, else a fresh read through readMetaFile.
564	func nextMeta(tg target, infos map[string]os.FileInfo, prior map[string]metaCursor) metaCursor {
565		m := metaCursor{rank: tg.fc.rank}
566		if tg.meta == "" {
567			return m
568		}
569		m.path = tg.meta
570		fi := infos[tg.meta]
571		if fi != nil {
572			m.size, m.modTime = fi.Size(), fi.ModTime()
573		}
574		if old, ok := prior[m.rank]; ok && old.unchangedSince(tg.meta, fi) {
575			return old
576		}
577		md, err := readMetaFile(tg.meta)
578		if err != nil {
579			m.unreadable = true
580			return m
581		}
582		m.typ, m.state, m.depth = md.AgentType, md.state(), md.SpawnDepth
583		return m
584	}
