27	// setClock stubs timeNow with a clock the test moves by assigning *now.
28	func setClock(t *testing.T, at time.Time) *time.Time {
29		t.Helper()
30		now := at
31		orig := timeNow
32		timeNow = func() time.Time { return now }
33		t.Cleanup(func() { timeNow = orig })
34		return &now
35	}
