193	// LastChange follows what changed, not what was looked at: an empty delta
194	// (including one where only an mtime moved) does not advance it, a non-empty
195	// one does and un-settles the session again.
196	func TestActivityFollowsRealChanges(t *testing.T) {
197		clock := setClock(t, actBase)
198		s := newSess(t)
199		s.build(metaSet{"a1": metaFinished}, actBase)
200		a := NewAggregate(s.parent())
201		readApply(t, a)
202		if got := a.Activity(); !got.LastChange.Equal(actBase) || got.Unfinished != 0 {
203			t.Fatalf("after the first read: %+v, want LastChange %v and no unfinished", got, actBase)
204		}
205		if !a.Activity().Settled(actBase.Add(actQuiet), actQuiet) {
206			t.Fatal("a finished session read once is settled after quiet")
207		}
208	
209		// An empty read much later: nothing changed, so LastChange stays.
210		*clock = actBase.Add(time.Hour)
211		if d := readApply(t, a); !d.Empty() {
212			t.Fatal("nothing was written, the delta must be Empty")
213		}
214		if got := a.Activity().LastChange; !got.Equal(actBase) {
215			t.Errorf("an Empty delta moved LastChange to %v", got)
216		}
217	
218		// Only the mtime moves (same size, same content): still not a change.
219		touch(t, s.parent(), actBase.Add(2*time.Hour))
220		*clock = actBase.Add(2 * time.Hour)
221		if d := readApply(t, a); !d.Empty() {
222			t.Fatal("an mtime alone must leave the delta Empty")
223		}
224		if got := a.Activity().LastChange; !got.Equal(actBase) {
225			t.Errorf("a bare mtime change moved LastChange to %v", got)
226		}
227	
228		// New lines: a real change.
229		at := actBase.Add(3 * time.Hour)
230		*clock = at
231		appendFile(t, s.parent(), ln("p3"))
232		touch(t, s.parent(), at)
233		if d := readApply(t, a); d.Empty() {
234			t.Fatal("appended lines must give a non-empty delta")
235		}
236		if got := a.Activity().LastChange; !got.Equal(at) {
237			t.Fatalf("LastChange = %v, want %v", got, at)
238		}
239		act := a.Activity()
